_RESOLUTION_TYPES = frozenset(
    status.value
    for status in (
        QuarantineStatus.IGNORED,
        QuarantineStatus.REPROCESSED,
        QuarantineStatus.EXPIRED,
    )
)


    def __post_init__(self) -> None:
        """Validate resolution info."""
        if self.resolution_type not in _RESOLUTION_TYPES:
            raise ValueError(
                f"Invalid resolution_type: {self.resolution_type}. "
                f"Must be one of {sorted(_RESOLUTION_TYPES)}."
            )
